export const GUIDANCE_LIMITATIONS = 'Conditional management information, not a diagnosis or guaranteed cure. These US extension sources may not fit your location or growing conditions. Confirm the cause locally before treatment or removing plants. No pesticide product or dose is prescribed here; follow locally approved labels and qualified advice.';
export function treatmentGuidance(record: Pick<Observation, 'disease' | 'is_mock' | 'analysis_status'>): Guidance | null {
  if (record.is_mock || record.analysis_status !== 'completed') return null;
  if (record.disease && Object.hasOwn(TOMATO_GUIDANCE, record.disease)) return TOMATO_GUIDANCE[record.disease];
  return { steps: ['No verified guidance is available for this prediction. Seek local diagnostic advice.'], sources: [], unavailable: true };
}
